export const PALM_ISLAND_PROJECTION = {
  "min_lat": -18.7764483,
  "max_lat": -18.6763813,
  "min_lon": 146.5482595,
  "max_lon": 146.6946398,
  "svg_width": 1000,
  "svg_height": 723,
  "pad": 0.05
} as const

/** Convert a real lat/lon into SVG coords inside the island viewBox. */
export function projectToIsland(lat: number, lon: number): { x: number; y: number } {
  const p = PALM_ISLAND_PROJECTION
  const x = p.pad * p.svg_width + (1 - 2 * p.pad) * p.svg_width * (lon - p.min_lon) / (p.max_lon - p.min_lon)
  const y = p.pad * p.svg_height + (1 - 2 * p.pad) * p.svg_height * (p.max_lat - lat) / (p.max_lat - p.min_lat)
  return { x, y }
}
